import 'dart:ui';import 'package:flutter/material.dart';import 'container_authentication_body.dart';class AuthenticationBody extends StatelessWidget {  const AuthenticationBody({    super.key,  });  @override  Widget build(BuildContext context) {    return Scaffold(        body: Stack(          children: [            Container(              decoration: BoxDecoration(                gradient: LinearGradient(                  begin: Alignment.centerLeft,                  end: Alignment.centerRight,                  colors: [                    Color(0xFF0E0F10),                    Color(0xFF222426),                    Color(0xFF151617),                    Color(0xFF1C1D1E),                    Color(0xFF44474B),                    Color(0xFF292B2D),                    Color(0xFF303236),                    Color(0xFF1C1D1E),                    Color(0xFF44474B),                    Color(0xFF292B2D),                    Color(0xFF303236),                  ],                  tileMode: TileMode.repeated,                ),              ),            ),            Positioned.fill(              child: BackdropFilter(                filter: ImageFilter.blur(sigmaX: 10, sigmaY: 10),                blendMode: BlendMode.darken,                child: Container(                  color: Colors.black.withAlpha(0x40),                ),              ),            ),            ContainerAuthenticationBody(),          ],        ));  }}